// Switch — Gtk.Switch
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles switch with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface SwitchProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.Switch */
  active?: boolean

  /** gboolean, from Gtk.Switch */
  state?: boolean
}

export function Switch({ className, children }: SwitchProps) {
  return (
    <div className={cn("p-[3px]", "rounded-[14px]", "bg-[color-mix(in_srgb,currentColor_15%,transparent)]", "outline-offset-[5px]", "transition-[outline-color,outline-width,outline-offset,background,box-shadow]", "duration-200", "ease-[cubic-bezier(0.25,0.46,0.45,0.94)]", className)}>
      {children}
    </div>
  )
}
